module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in     ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [9:0] accumulated_sum;
reg [1:0] counter; // Counter to keep track of valid inputs

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        accumulated_sum <= 10'b0;
        counter <= 2'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin
        if (valid_in) begin
            accumulated_sum <= accumulated_sum + data_in; // Accumulate data
            counter <= counter + 1'b1; // Increment counter
        end

        if (counter == 2'b11) begin // Check if we have received 4 inputs
            valid_out <= 1'b1; // Set valid out high
            data_out <= accumulated_sum; // Output accumulated sum
            // Reset for next accumulation
            accumulated_sum <= 10'b0;
            counter <= 2'b0;
        end else begin
            valid_out <= 1'b0; // Reset valid out
        end
    end
end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in     ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [9:0] accumulated_sum;
reg [1:0] count; // 2-bit counter to count up to 4

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        accumulated_sum <= 10'b0;
        count <= 2'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin
        if (valid_in) begin
            accumulated_sum <= accumulated_sum + {2'b0, data_in}; // Add 8-bit data to 10-bit sum
            count <= count + 1'b1; // Increment count

            if (count == 2'b11) begin // Check if count reached 4 (2'b11 + 1)
                valid_out <= 1'b1; // Set valid_out high
                data_out <= accumulated_sum; // Output the accumulated sum
                // Reset for next accumulation
                accumulated_sum <= 10'b0;
                count <= 2'b0;
            end else begin
                valid_out <= 1'b0; // Keep valid_out low if not yet reached 4
            end
        end else begin
            valid_out <= 1'b0; // Ensure valid_out is low if no valid input
        end
    end
end

endmodule

