    end else begin
        if (valid_in) begin
            accumulated_sum <= accumulated_sum + {2'b0, data_in}; // Add 8-bit data to 10-bit sum
            counter <= counter + 1;
            if (counter == 2'b11) begin // When counter reaches 4
                valid_out <= 1'b1;
                data_out <= accumulated_sum;
                accumulated_sum <= 10'b0; // Reset accumulated sum
                counter <= 2'b0; // Reset counter
