            valid_out <= 1'b0; // Reset valid_out if no valid input
        end
    end
end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in     ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [9:0] accumulator;
reg [1:0] counter;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        accumulator <= 10'b0;
        counter <= 2'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin
        if (valid_in) begin
            accumulator <= accumulator + {2'b0, data_in}; // Accumulate 8-bit input to 10-bit
            counter <= counter + 2'b1;
            if (counter == 2'b11) begin
                valid_out <= 1'b1; // Set valid_out high for one cycle
                data_out <= accumulator; // Output the accumulated result
                // Reset for next accumulation
                accumulator <= 10'b0;
                counter <= 2'b0;
            end else begin
                valid_out <= 1'b0; // Keep valid_out low until counter reaches 4
            end
        end else begin
            valid_out <= 1'b0; // Reset valid_out if no valid input
        end
    end
end

endmodule

module accu(
    input               clk         ,   
    input               rst_n       ,
    input       [7:0]   data_in     ,
    input               valid_in     ,

    output  reg         valid_out     ,
    output  reg [9:0]   data_out
);

reg [9:0] accumulator;
reg [1:0] count; // Counter for valid inputs

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        accumulator <= 10'b0;
        count <= 2'b0;
        valid_out <= 1'b0;
        data_out <= 10'b0;
    end else begin
        if (valid_in) begin
            if (count < 2'b11) begin // Count from 0 to 3 (4 valid inputs)
                accumulator <= accumulator + {2'b0, data_in}; // Accumulate data
                count <= count + 1'b1;
                valid_out <= 1'b0; // Hold valid_out low until count reaches 4
            end
            if (count == 2'b11) begin // When 4 valid inputs have been received
                data_out <= accumulator; // Output the accumulated sum
                valid_out <= 1'b1; // Set valid_out high for one cycle
                // Reset accumulator and count for next accumulation
                accumulator <= 10'b0;
                count <= 2'b0;
            end
        end else begin
            valid_out <= 1'b0; // Reset valid_out if no valid input
        end
    end
end

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    wire [7:0] carry; // Internal carry wires

    // Full adder for bit 0
    assign sum[0] = a[0] ^ b[0] ^ cin;
    assign carry[0] = (a[0] & b[0]) | (cin & (a[0] ^ b[0]));

    // Full adder for bit 1
    assign sum[1] = a[1] ^ b[1] ^ carry[0];
    assign carry[1] = (a[1] & b[1]) | (carry[0] & (a[1] ^ b[1]));

    // Full adder for bit 2
    assign sum[2] = a[2] ^ b[2] ^ carry[1];
    assign carry[2] = (a[2] & b[2]) | (carry[1] & (a[2] ^ b[2]));

    // Full adder for bit 3
    assign sum[3] = a[3] ^ b[3] ^ carry[2];
    assign carry[3] = (a[3] & b[3]) | (carry[2] & (a[3] ^ b[3]));

    // Full adder for bit 4
    assign sum[4] = a[4] ^ b[4] ^ carry[3];
    assign carry[4] = (a[4] & b[4]) | (carry[3] & (a[4] ^ b[4]));

    // Full adder for bit 5
    assign sum[5] = a[5] ^ b[5] ^ carry[4];
    assign carry[5] = (a[5] & b[5]) | (carry[4] & (a[5] ^ b[5]));

    // Full adder for bit 6
    assign sum[6] = a[6] ^ b[6] ^ carry[5];
    assign carry[6] = (a[6] & b[6]) | (carry[5] & (a[6] ^ b[6]));

    // Full adder for bit 7
    assign sum[7] = a[7] ^ b[7] ^ carry[6];
    assign cout = (a[7] & b[7]) | (carry[6] & (a[7] ^ b[7]));

endmodule

