module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output reg [DATA_WIDTH:0] result,
    output reg o_en
);

    reg [DATA_WIDTH-1:0] a_reg [0:STG_WIDTH-1];
    reg [DATA_WIDTH-1:0] b_reg [0:STG_WIDTH-1];
    reg [DATA_WIDTH:0] sum_reg [0:STG_WIDTH-1];
    reg [STG_WIDTH-1:0] carry;

    integer i;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < STG_WIDTH; i = i + 1) begin
                a_reg[i] <= 0;
                b_reg[i] <= 0;
                sum_reg[i] <= 0;
            end
            o_en <= 0;
            result <= 0;
        end else if (i_en) begin
            a_reg[0] <= adda;
            b_reg[0] <= addb;
            for (i = 1; i < STG_WIDTH; i = i + 1) begin
                a_reg[i] <= a_reg[i-1];
                b_reg[i] <= b_reg[i-1];
                sum_reg[i] <= a_reg[i] + b_reg[i] + carry[i-1];
                carry[i] <= (a_reg[i] & b_reg[i]) | (carry[i-1] & (a_reg[i] ^ b_reg[i]));
            end
            sum_reg[0] <= a_reg[0] + b_reg[0];
            carry[0] <= 0;
            result <= sum_reg[STG_WIDTH-1];
            o_en <= 1;
        end else begin
            o_en <= 0;
        end
    end

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output reg [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] stage_a [0:STG_WIDTH-1];
reg [DATA_WIDTH-1:0] stage_b [0:STG_WIDTH-1];
reg [DATA_WIDTH:0] carry [0:STG_WIDTH-1];
integer i;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        for (i = 0; i < STG_WIDTH; i = i + 1) begin
            stage_a[i] <= 0;
            stage_b[i] <= 0;
            carry[i] <= 0;
        end
        result <= 0;
        o_en <= 0;
    end else if (i_en) begin
        stage_a[0] <= adda;
        stage_b[0] <= addb;
        carry[0] <= 0; // Initial carry is zero

        for (i = 1; i < STG_WIDTH; i = i + 1) begin
            stage_a[i] <= stage_a[i-1];
            stage_b[i] <= stage_b[i-1];
            carry[i] <= {1'b0, stage_a[i-1]} + {1'b0, stage_b[i-1]} + carry[i-1];
        end

        result <= carry[STG_WIDTH-1]; // Final result includes carry out
        o_en <= 1; // Output enable
    end else begin
        o_en <= 0; // Disable output if not enabled
    end
end

endmodule

module adder_pipe_64bit
#(
    parameter DATA_WIDTH = 64,
    parameter STG_WIDTH = 16
)
(
    input clk,
    input rst_n,
    input i_en,
    input [DATA_WIDTH-1:0] adda,
    input [DATA_WIDTH-1:0] addb,
    output reg [DATA_WIDTH:0] result,
    output reg o_en
);

reg [DATA_WIDTH-1:0] sum_stage1, sum_stage2;
reg [DATA_WIDTH-1:0] carry_stage1, carry_stage2;
reg [DATA_WIDTH:0] final_sum;
reg [1:0] stage;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        sum_stage1 <= 0;
        sum_stage2 <= 0;
        carry_stage1 <= 0;
        carry_stage2 <= 0;
        final_sum <= 0;
        o_en <= 0;
        stage <= 0;
    end else begin
        if (i_en) begin
            case (stage)
                2'b00: begin
                    sum_stage1 <= adda + addb;
                    carry_stage1 <= (adda & addb) << 1; // Generate carry
                    stage <= stage + 1;
                end
                2'b01: begin
                    sum_stage2 <= sum_stage1 + carry_stage1;
                    carry_stage2 <= (sum_stage1 & carry_stage1) << 1; // Generate next carry
                    stage <= stage + 1;
                end
                2'b10: begin
                    final_sum <= sum_stage2 + carry_stage2;
                    o_en <= 1; // Result is ready
                    stage <= 0; // Reset stage for next operation
                end
            endcase
        end
    end
end

always @(posedge clk) begin
    if (stage == 2'b10) begin
        result <= final_sum; // Output final result
    end
end

endmodule

