                carry_reg[i] <= (sum_reg[i-1] & carry_reg[i-1]) >> 1; // propagate carry
            end
            final_result <= {carry_reg[STG_WIDTH-1], sum_reg[STG_WIDTH-1]};
            o_en <= 1;
        end
    end
end

