module asyn_fifo#(
	parameter	WIDTH = 8,
	parameter 	DEPTH = 16
)(
	input 					wclk	, 
	input 					rclk	,   
	input 					wrstn	,
	input					rrstn	,
	input 					winc	,
	input 			 		rinc	,
	input 		[WIDTH-1:0]	wdata	,

	output wire				wfull	,
	output wire				rempty	,
	output wire [WIDTH-1:0]	rdata
);

parameter ADDR_WIDTH = $clog2(DEPTH);
reg [WIDTH-1:0] ram [0:DEPTH-1];

reg [ADDR_WIDTH-1:0] waddr_bin, raddr_bin;
reg [ADDR_WIDTH-1:0] waddr_gray, raddr_gray;
reg [ADDR_WIDTH-1:0] waddr_sync1, waddr_sync2;
reg [ADDR_WIDTH-1:0] raddr_sync1, raddr_sync2;

reg [ADDR_WIDTH:0] wptr, rptr;

wire wfull_int;
wire rempty_int;

assign wfull = wfull_int;
assign rempty = rempty_int;
assign rdata = ram[raddr_bin];

always @(posedge wclk or negedge wrstn) begin
	if (!wrstn) begin
		waddr_bin <= 0;
		wptr <= 0;
	end else if (winc && !wfull_int) begin
		ram[waddr_bin] <= wdata;
		waddr_bin <= waddr_bin + 1;
		wptr <= wptr + 1;
	end
end

always @(posedge rclk or negedge rrstn) begin
	if (!rrstn) begin
		raddr_bin <= 0;
		rptr <= 0;
	end else if (rinc && !rempty_int) begin
		raddr_bin <= raddr_bin + 1;
		rptr <= rptr + 1;
