input CLK,RST;
output [5:0] Hours,Mins,Secs;
reg [5:0] Hours,Mins,Secs;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        Secs <= 6'b0;
        Mins <= 6'b0;
        Hours <= 6'b0;
    end else begin
        if (Secs == 59) begin
            Secs <= 6'b0;
            if (Mins == 59) begin
                Mins <= 6'b0;
                if (Hours == 23) begin
                    Hours <= 6'b0;
