always @(posedge clk or negedge rst_n) begin
	if (!rst_n) begin
		prev_a <= 0;
		rise <= 0;
		down <= 0;
	end else begin
		rise <= (a == 1 && prev_a == 0) ? 1 : 0;
		down <= (a == 0 && prev_a == 1) ? 1 : 0;
		prev_a <= a;
	end
end

