module multi_16bit(
    input clk,          // Chip clock signal.
    input rst_n,        // Active-low reset signal. Defined as 0 for chip reset; defined as 1 for reset signal inactive.
    input start,        // Chip enable signal. 
    input [15:0] ain,   // Input a (multiplicand) with a data width of 16 bits.
    input [15:0] bin,   // Input b (multiplier) with a data width of 16 bits.

    output reg [31:0] yout, // Product output with a data width of 32 bits.
    output reg done         // Chip output flag signal. Defined as 1 indicates multiplication operation completion.
);

reg [15:0] areg;  // Register for multiplicand
reg [15:0] breg;  // Register for multiplier
reg [31:0] yout_r; // Register for accumulated product
reg [4:0] i;      // Shift count register

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        areg <= 16'b0;
        breg <= 16'b0;
        yout_r <= 32'b0;
        i <= 5'b0;
        done <= 1'b0;
    end else if (start) begin
        if (i == 5'b0) begin
            areg <= ain;
            breg <= bin;
            yout_r <= 32'b0;
            i <= 5'b1;
            done <= 1'b0;
        end else if (i < 5'd17) begin
            if (areg[i-1]) begin
                yout_r <= yout_r + (breg << (i-1));
            end
            i <= i + 1;
        end else if (i == 5'd17) begin
            done <= 1'b1;
            yout <= yout_r;
        end else begin
            done <= 1'b0;
        end
    end
end

endmodule

