module multi_booth_8bit (p, rdy, clk, reset, a, b);
    input clk, reset;
    input [7:0] a, b;
    output reg [15:0] p;
    output reg rdy;

    reg [15:0] multiplicand, multiplier;
    reg [4:0] ctr;
    reg [15:0] temp;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            p <= 16'b0;
            rdy <= 1'b0;
            ctr <= 5'b0;
            multiplicand <= {8'b0, a}; // Sign-extend a
            multiplier <= {8'b0, b};    // Sign-extend b
        end else if (ctr < 16) begin
            case ({multiplier[1:0]})
                2'b01: p <= p + multiplicand;         // Add multiplicand
                2'b10: p <= p - multiplicand;         // Subtract multiplicand
                default: ;                            // Do nothing for 00 and 11
            endcase

            // Arithmetic right shift
            temp = {p[15], p[15:1]}; // Preserve sign bit
            p <= temp;

            // Left shift multiplicand
            multiplicand <= multiplicand << 1;

            // Update counter
            ctr <= ctr + 1;
        end else begin
            rdy <= 1'b1; // Set ready signal when done
        end
    end
endmodule

