module alu(
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output zero,
    output reg carry,
    output negative,
    output reg overflow,
    output reg flag
    );

    always @(*) begin
        carry = 0;
        overflow = 0;
        flag = 1'bz; // Default to high-impedance

        case (aluc)
