					cnt <= cnt - 1;
			end
		end
	end

	always @(*) begin
		case (state)
			idle: next_state = s1_red;
			s1_red: begin
				if (cnt == 0)
					next_state = s3_green;
				else
					next_state = s1_red;
			end
			s2_yellow: begin
				if (cnt == 0)
					next_state = s1_red;
				else
					next_state = s2_yellow;
			end
			s3_green: begin
				if (cnt == 0)
					next_state = s2_yellow;
				else
					next_state = s3_green;
			end
			default: next_state = idle;
		endcase
	end

	always @(*) begin
		red = 0;
		yellow = 0;
		green = 0;
		case (state)
			s1_red: red = 1;
			s2_yellow: yellow = 1;
			s3_green: green = 1;
		endcase
	end

endmodule

module traffic_light
    (
		input rst_n, 
        input clk, 
        input pass_request,
		output wire[7:0] clock,
        output reg red,
		output reg yellow,
		output reg green
    );

    reg [1:0] state, next_state;
    reg [7:0] cnt;

    assign clock = cnt;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= idle;
            cnt <= 8'd10; // Initialize counter to 10
        end else begin
            if (cnt > 0)
                cnt <= cnt - 1;
            else
                state <= next_state;
        end
    end

    always @(*) begin
        case (state)
            idle: begin
                red = 1;
                yellow = 0;
                green = 0;
                next_state = s1_red;
            end

            s1_red: begin
                red = 1;
                yellow = 0;
                green = 0;
                if (cnt == 0) begin
                    cnt = 8'd60; // Set counter for green
                    next_state = s3_green;
                end else begin
                    next_state = s1_red;
                end
            end

            s2_yellow: begin
                red = 0;
                yellow = 1;
                green = 0;
                if (cnt == 0) begin
                    cnt = 8'd10; // Reset counter for red
                    next_state = s1_red;
                end else begin
                    next_state = s2_yellow;
                end
            end

            s3_green: begin
                red = 0;
                yellow = 0;
                green = 1;
                if (pass_request && cnt > 8'd10) begin
                    cnt = 8'd10; // Override green time
                end
                if (cnt == 0) begin
                    cnt = 8'd5; // Set counter for yellow
                    next_state = s2_yellow;
                end else begin
                    next_state = s3_green;
                end
            end

            default: begin
                next_state = idle;
            end
        endcase
    end

endmodule

module traffic_light
    (
		input rst_n, 
        input clk, 
        input pass_request,
		output wire[7:0] clock,
        output reg red,
		output reg yellow,
		output reg green
    );

	parameter 	idle = 2'd0,
				s1_red = 2'd1,
				s2_yellow = 2'd2,
				s3_green = 2'd3;

	reg [1:0] state, next_state;
	reg [7:0] cnt;

	assign clock = cnt;

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			state <= idle;
			cnt <= 8'd10; // Initialize to red duration
		end else begin
			state <= next_state;
		end
	end

	always @(posedge clk) begin
		if (state == s3_green) begin
			if (cnt > 8'd10 && pass_request) begin
				cnt <= 8'd10; // Override green duration
			end else if (cnt > 0) begin
				cnt <= cnt - 1; // Count down
			end
		end else if (cnt > 0) begin
			cnt <= cnt - 1; // Count down for other states
		end
	end

	always @(*) begin
		case (state)
			idle: begin
				next_state = s1_red;
				red = 1;
				yellow = 0;
				green = 0;
			end
			s1_red: begin
				if (cnt == 0) begin
					next_state = s3_green;
					cnt = 8'd60; // Set green duration
				end else begin
					next_state = s1_red;
				end
				red = 1;
				yellow = 0;
				green = 0;
			end
			s2_yellow: begin
				if (cnt == 0) begin
					next_state = s1_red;
					cnt = 8'd10; // Set red duration
				end else begin
					next_state = s2_yellow;
				end
				red = 0;
				yellow = 1;
				green = 0;
			end
			s3_green: begin
				if (cnt == 0) begin
					next_state = s2_yellow;
					cnt = 8'd5; // Set yellow duration
				end else begin
					next_state = s3_green;
				end
				red = 0;
				yellow = 0;
				green = 1;
			end
			default: begin
				next_state = idle;
				red = 0;
				yellow = 0;
				green = 0;
			end
		endcase
	end

endmodule

module width_8to16(
	input                   clk         ,   
	input                   rst_n       ,
	input                   valid_in    ,
	input       [7:0]      data_in     ,

	output  reg            valid_out    ,
	output  reg [15:0]     data_out     
);

	reg [7:0] data_lock;
	reg       first_data_received;

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			data_lock <= 8'b0;
			data_out <= 16'b0;
			valid_out <= 1'b0;
			first_data_received <= 1'b0;
		end else begin
			if (valid_in) begin
				if (!first_data_received) begin
					data_lock <= data_in;
					first_data_received <= 1'b1;
				end else begin
					data_out <= {data_lock, data_in};
					valid_out <= 1'b1;
					first_data_received <= 1'b0; // Reset for next pair
				end
			end else begin
				valid_out <= 1'b0; // Reset valid_out if not valid_in
			end
		end
	end

endmodule

module width_8to16(
	input 				   clk 		,   
	input 				   rst_n		,
	input				      valid_in	,
	input	   [7:0]		   data_in	,

 	output	reg			valid_out,
	output   reg [15:0]	data_out
);

	reg [7:0] data_lock;
	reg [1:0] state; // 0: waiting for first data, 1: waiting for second data

	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			data_lock <= 8'b0;
			data_out <= 16'b0;
			valid_out <= 1'b0;
			state <= 2'b00;
		end else begin
			case (state)
				2'b00: begin // Waiting for first data
					if (valid_in) begin
						data_lock <= data_in;
						state <= 2'b01;
						valid_out <= 1'b0;
					end
				end
				2'b01: begin // Waiting for second data
					if (valid_in) begin
						data_out <= {data_lock, data_in};
						valid_out <= 1'b1;
						state <= 2'b00; // Go back to waiting for first data
					end
				end
			endcase
		end
	end

endmodule

